    <Composition id="Intro" component={Intro} durationInFrames={totalFrames(INTRO_SCENES)} {...base} />
    <Folder name="Scenes">
      {SCENES.map((scene, i) =>
        scene.component ? (
          <Composition
            key={scene.id}
            id={`Scene-${scene.id}`}
            component={SoloScene}
            defaultProps={{ index: i }}
            durationInFrames={sequenceFrames(SCENES, i)}
